perator(\n        task_id="test_postgres",\n        python_callable=_count_rows,\n        op_kwargs={"conn_id": POSTGRES_CONN_ID, "label": "postgres"},\n    )\n\n    test_mssql = PythonOperator(\n        task_id="test_mssql",\n        python_callable=_count_rows,\n        op_kwargs={"conn_id": MSSQL_CONN_ID, "label": "mssql"},\n    )\n\n    test_oracle = PythonOperator(\n        task_id="test_oracle",\n        python_callable=_count_rows,\n        op_kwargs={"conn_id": ORACLE_CONN_ID, "label": "oracle"},\n    )\n\n    # Intentionally no dependency edges: connection checks should run in parallel.\n    parallel_connection_checks = [test_postgres, test_mssql, test_oracle]\n	38672d96d313c949035d09c124fba585	019dbb27-4fb4-71e1-a493-5e3224d4a4c7
